css:
.loader { width: var(--loader-size); height: calc(var(--loader-size) * .12); border-radius: 9999px; background: color-mix(in srgb, var(--loader-color) 16%, transparent); overflow: hidden; }
.loader span { display: block; width: 100%; height: 100%; background: linear-gradient(90deg, transparent, color-mix(in srgb, var(--loader-color) 70%, transparent), transparent); animation: twShimmer calc(var(--loader-speed) * 1.5) ease-in-out infinite; }
@keyframes twShimmer { 0% { transform: translateX(-100%); } 100% { transform: translateX(100%); } }
